
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_gaploc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_gaploc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.067121406336263e-02, -7.783074032462282e-02, -7.376059389143927e-02, -6.799914421000507e-02, -6.006484254925646e-02, -4.973804511435858e-02, -3.762367789439041e-02, -2.557722216427177e-02, -1.601882669330673e-02, -1.037188089103815e-02, -8.569479952018993e-03, -5.136508664945071e-02, -5.537012038992287e-02, -4.076780916875458e-02, -9.456465330529806e-03, -4.233069816833623e-03, -2.098340358292494e-03, -3.865941082255177e-04, -1.520530096291637e-05, -1.648865855294316e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


